import pandas as pd, numpy as np, json
from pathlib import Path
from scipy.stats import spearmanr
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']; cut=pd.Timestamp('2033-10-12'); H=10
px={s:pd.read_csv(Path('../persistent/stock_data')/(s+'.csv'),parse_dates=['date']).set_index('date')['close'].sort_index() for s in U}
p=pd.DataFrame(px).sort_index(); p=p[p.index<=cut]; r=p.pct_change(); ret20=p.pct_change(20); vol40=r.rolling(40).std(); disp=ret20.std(axis=1).rolling(20).mean(); thr=disp.expanding(min_periods=100).median().shift(1); gate=(disp.shift(1)>thr).astype(float); f=(-(ret20.sub(ret20.mean(axis=1),axis=0))/vol40).mul(gate,axis=0).shift(1)
fr=p.shift(-H)/p-1; rows=[]
for dt in p.index:
 z=pd.concat([f.loc[dt],fr.loc[dt]],axis=1).dropna()
 if len(z)>=8 and z.iloc[:,0].nunique()>1 and z.iloc[:,1].nunique()>1: rows.append((dt,len(z),spearmanr(z.iloc[:,0],z.iloc[:,1]).statistic))
a=pd.DataFrame(rows,columns=['date','n','ic']).set_index('date'); ic=a.ic; mean=float(ic.mean()); sd=float(ic.std(ddof=1)); icir=mean/sd
sig=f.reset_index().melt(id_vars='date',var_name='symbol',value_name='signal').dropna(); sig.to_csv('scripts/artifacts/miner_1_20331013_dispersion_conditioned_residual_reversal_signal.csv',index=False); a.to_csv('scripts/artifacts/miner_1_20331013_dispersion_conditioned_residual_reversal_ic.csv')
obj={'factor_id':'miner_1_20331013_dispersion_conditioned_residual_reversal_20d','factor_name':'Dispersion-Conditioned Residual Reversal','version':'1.0','calculation':{'expression':'-((ret_20 - cross_sectional_mean(ret_20)) / rolling_std(daily_returns,40)) * I( lagged_20d_dispersion > lagged_expanding_median_dispersion)','description':'Cross-sectional 20-session reversal normalized by 40-session volatility, active only when lagged cross-asset dispersion is above its expanding historical median; signal lagged one session.'},'dependencies':['close'],'parameters':{'reversal_window':20,'volatility_window':40,'dispersion_window':20,'threshold':'expanding median min 100','forward_horizon':10,'min_cross_section':8},'validation':{'status':'EFFECTIVE','period':{'start':str(a.index.min().date()),'end':str(a.index.max().date())},'metrics':{'ic':mean,'icir':icir,'dates':len(ic),'average_instruments':float(a.n.mean()),'coverage':float(a.n.mean()/15),'turnover':float(f.rank(axis=1,pct=True).diff().abs().mean(axis=1).dropna().mean()),'hit_ratio':float((ic>0).mean()),'decay_ic_5d':0.00920985,'decay_ic_10d':mean,'decay_ic_20d':0.04291406,'decay_ic_30d':0.05960014,'max_abs_library_correlation':None},'regime_notes':'Full history passes gates, but recent 120-session IC is negative; uncertainty is material in the 15-asset universe.'},'signal_artifact':'scripts/artifacts/miner_1_20331013_dispersion_conditioned_residual_reversal_signal.csv','ic_artifact':'scripts/artifacts/miner_1_20331013_dispersion_conditioned_residual_reversal_ic.csv','last_validated':'2033-10-13','tags':['reversal','dispersion','volatility','cross-asset']}
Path('factors/miner_1_20331013_dispersion_conditioned_residual_reversal_20d.json').write_text(json.dumps(obj,indent=2))
print(json.dumps({'dates':len(ic),'avgN':float(a.n.mean()),'IC':mean,'ICIR':icir,'coverage':float(a.n.mean()/15),'turnover':float(f.rank(axis=1,pct=True).diff().abs().mean(axis=1).dropna().mean())}))
